// Mutex thread test\nuse std::sync::{Arc, Mutex};\nuse std::thread;\nfn main() {\n    let counter = Arc::new(Mutex::new(0));\n    let handles: Vec<_> = (0..5).map(|_| {\n        let c = Arc::clone(&counter);\n        thread::spawn(move || { *c.lock().unwrap() += 1; })\n    }).collect();\n    for h in handles { h.join().unwrap(); }\n    println\!("{}", *counter.lock().unwrap());\n}
